solution.gigasecond.zig:
const std = @import("std");

/// Gregorian civil date/time; timezone interpretation is retained by the caller.
pub const DateTime = struct { year: i32, month: u8, day: u8, hour: u8 = 0, minute: u8 = 0, second: u8 = 0 };
fn leap(year: i32) bool {
    return @mod(year, 4) == 0 and (@mod(year, 100) != 0 or @mod(year, 400) == 0);
}
fn monthDays(year: i32, month: u8) u8 {
    return switch (month) {
        2 => if (leap(year)) 29 else 28,
        4, 6, 9, 11 => 30,
        else => 31,
    };
}
pub fn add(moment: DateTime) !DateTime {
    if (moment.month < 1 or moment.month > 12 or moment.day < 1 or moment.day > monthDays(moment.year, moment.month) or moment.hour > 23 or moment.minute > 59 or moment.second > 59) return error.InvalidDateTime;
    var result = moment;
    const seconds: u64 = @as(u64, moment.hour) * 3600 + @as(u64, moment.minute) * 60 + moment.second + 1_000_000_000;
    result.hour = @intCast(seconds % 86400 / 3600);
    result.minute = @intCast(seconds % 3600 / 60);
    result.second = @intCast(seconds % 60);
    var days = seconds / 86400;
    while (days > 0) {
        const remaining = monthDays(result.year, result.month) - result.day;
        if (days <= remaining) {
            result.day += @intCast(days);
            break;
        }
        days -= @as(u64, remaining) + 1;
        result.day = 1;
        if (result.month == 12) {
            result.month = 1;
            result.year += 1;
        } else result.month += 1;
    }
    return result;
}

tests.test_gigasecond.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("gigasecond.zig");

test "dates, full times, midnight rollover and Gregorian leap years" {
    try t.expectEqualDeep(m.DateTime{ .year = 2043, .month = 1, .day = 1, .hour = 1, .minute = 46, .second = 40 }, try m.add(.{ .year = 2011, .month = 4, .day = 25 }));
    try t.expectEqualDeep(m.DateTime{ .year = 2009, .month = 2, .day = 19, .hour = 1, .minute = 46, .second = 40 }, try m.add(.{ .year = 1977, .month = 6, .day = 13 }));
    try t.expectEqualDeep(m.DateTime{ .year = 1991, .month = 3, .day = 27, .hour = 1, .minute = 46, .second = 40 }, try m.add(.{ .year = 1959, .month = 7, .day = 19 }));
    try t.expectEqualDeep(m.DateTime{ .year = 2046, .month = 10, .day = 2, .hour = 23, .minute = 46, .second = 40 }, try m.add(.{ .year = 2015, .month = 1, .day = 24, .hour = 22 }));
    try t.expectEqualDeep(m.DateTime{ .year = 2046, .month = 10, .day = 3, .hour = 1, .minute = 46, .second = 39 }, try m.add(.{ .year = 2015, .month = 1, .day = 24, .hour = 23, .minute = 59, .second = 59 }));
    try t.expectError(error.InvalidDateTime, m.add(.{ .year = 1900, .month = 2, .day = 29 }));
}
